12	// SharedTx can be used to wrap a test transaction in cases where multiple
13	// callers may want to access it concurrently during the course of a single test
14	// case. Normally this is not allowed and an access will error with "conn busy"
15	// if another caller is already using it.
16	//
17	// This is a test-only construct because in non-test environments an executor is
18	// a full connection pool which can support concurrent access without trouble.
19	// Many test cases use single test transactions, and that's where code written
20	// to use a connection pool can become problematic.
21	//
22	// SharedTx uses a channel for synchronization and does *not* guarantee FIFO
23	// ordering for callers.
24	//
25	// Avoid using SharedTx if possible because while it works, problems
26	// encountered by use of concurrent accesses will be more difficult to debug
27	// than otherwise, so it's better to not go there at all if it can be avoided.
28	type SharedTx struct {
29		inner pgx.Tx
30		wait  chan struct{}
31	}
32	
33	func NewSharedTx(tx pgx.Tx) *SharedTx {
34		wait := make(chan struct{}, 1)
35	
36		// Send one initial signal in so that the first caller is able to acquire a
37		// lock.
38		wait <- struct{}{}
39	
40		return &SharedTx{
41			inner: tx,
42			wait:  wait,
43		}
44	}
45	
46	func (e *SharedTx) Begin(ctx context.Context) (pgx.Tx, error) {
47		e.lock()
48		// no unlock until transaction commit/rollback
49	
50		tx, err := e.inner.Begin(ctx)
51		if err != nil {
52			e.unlock()
53			return nil, err
54		}
55	
56		// shared tx is unlocked when the transaction is committed or rolled back
57		return &SharedSubTx{sharedTxDerivative{sharedTx: e}, tx}, nil
58	}
59	
60	func (e *SharedTx) CopyFrom(ctx context.Context, tableName pgx.Identifier, columnNames []string, rowSrc pgx.CopyFromSource) (int64, error) {
61		e.lock()
62		defer e.unlock()
63	
64		return e.inner.CopyFrom(ctx, tableName, columnNames, rowSrc)
65	}
66	
67	func (e *SharedTx) Exec(ctx context.Context, query string, args ...any) (pgconn.CommandTag, error) {
68		e.lock()
69		defer e.unlock()
70	
71		return e.inner.Exec(ctx, query, args...)
72	}
73	
74	func (e *SharedTx) Query(ctx context.Context, query string, args ...any) (pgx.Rows, error) {
75		e.lock()
76		// no unlock until rows close or return on error condition
77	
78		rows, err := e.inner.Query(ctx, query, args...)
79		if err != nil {
80			e.unlock()
81			return nil, err
82		}
83	
84		// executor is unlocked when rows are closed
85		return &SharedTxRows{sharedTxDerivative{sharedTx: e}, rows}, nil
86	}
87	
88	func (e *SharedTx) QueryRow(ctx context.Context, query string, args ...any) pgx.Row {
89		e.lock()
90		// no unlock until row scan
91	
92		row := e.inner.QueryRow(ctx, query, args...)
93	
94		// executor is unlocked when row is scanned
95		return &SharedTxRow{sharedTxDerivative{sharedTx: e}, row}
96	}
97	
98	//
99	// These are all implemented so that a SharedTx can be used as a pgx.Tx, but are
100	// all non-functional.
101	//
102	
103	func (e *SharedTx) Conn() *pgx.Conn                  { panic("not implemented") }
104	func (e *SharedTx) Commit(ctx context.Context) error { panic("not implemented") }
105	func (e *SharedTx) LargeObjects() pgx.LargeObjects   { panic("not implemented") }
106	func (e *SharedTx) Prepare(ctx context.Context, name, sql string) (*pgconn.StatementDescription, error) {
107		panic("not implemented")
108	}
109	func (e *SharedTx) Rollback(ctx context.Context) error { panic("not implemented") }
110	func (e *SharedTx) SendBatch(ctx context.Context, b *pgx.Batch) pgx.BatchResults {
111		panic("not implemented")
112	}
113	
114	func (e *SharedTx) lock() {
115		select {
116		case <-e.wait:
117			// success
118	
119		case <-time.After(5 * time.Second):
120			panic("sharedtx: Timed out trying to acquire lock on SharedTx")
121		}
122	}
123	
124	func (e *SharedTx) unlock() {
125		select {
126		case e.wait <- struct{}{}:
127		default:
128			panic("wait channel was already unlocked which should not happen; BUG!")
129		}
130	}
