132	type sharedTxDerivative struct {
133		once     sync.Once // used to guarantee executor only unlocked once
134		sharedTx *SharedTx
135	}
136	
137	func (d *sharedTxDerivative) unlockParent() {
138		d.once.Do(func() {
139			d.sharedTx.unlock()
140		})
141	}
142	
143	// SharedTxRow wraps a pgx.Row such that it unlocks SharedExecutor when
144	// the row finishes scanning.
145	type SharedTxRow struct {
146		sharedTxDerivative
147	
148		innerRow pgx.Row
149	}
150	
151	func (r *SharedTxRow) Scan(dest ...any) error {
152		defer r.unlockParent()
153		return r.innerRow.Scan(dest...)
154	}
155	
156	// SharedTxRows wraps a pgx.Rows such that it unlocks SharedExecutor when
157	// the rows are closed.
158	type SharedTxRows struct {
159		sharedTxDerivative
160	
161		innerRows pgx.Rows
162	}
163	
164	func (r *SharedTxRows) Close() {
165		defer r.unlockParent()
166		r.innerRows.Close()
167	}
168	
