170	// All of these are simple pass throughs.
171	//
172	
173	func (r *SharedTxRows) CommandTag() pgconn.CommandTag { return r.innerRows.CommandTag() }
174	func (r *SharedTxRows) Conn() *pgx.Conn               { return nil }
175	func (r *SharedTxRows) Err() error                    { return r.innerRows.Err() }
176	func (r *SharedTxRows) FieldDescriptions() []pgconn.FieldDescription {
