// parsePlaceholderCasts scans SQL for `$n` placeholders and records the SQL cast
// (if any) that each is bound to. Both the `$n::type` and `CAST($n AS type)`
// forms are recognized. When a placeholder appears more than once, a bytea cast
// takes precedence so that genuine byte payloads are always preserved.
func parsePlaceholderCasts(sql string) map[int]castKind {
